import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor sigmoid_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <int VecSize>
__global__ void sigmoid_kernel(const float* __restrict__ X,
                                float* __restrict__ Y,
                                int64_t N)
{
  constexpr int NumFloat4 = VecSize / 4;
  int64_t tid    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t idx    = tid * VecSize;
  int64_t stride = (int64_t)gridDim.x * blockDim.x * VecSize;
  for (; idx < N; idx += stride) {
    if (idx + VecSize <= N) {
      // Wider vectorized 128-bit-per-float4 loads/stores. Multiple
      // float4 groups per thread increase memory-level parallelism
      // (more outstanding loads in flight per thread) which helps
      // saturate DRAM bandwidth further for this memory-bound kernel.
      #pragma unroll
      for (int v = 0; v < NumFloat4; ++v) {
        float4 val = __ldg(reinterpret_cast<const float4*>(X + idx + v * 4));
        float4 r;
        r.x = 1.0f / (1.0f + __expf(-val.x));
        r.y = 1.0f / (1.0f + __expf(-val.y));
        r.z = 1.0f / (1.0f + __expf(-val.z));
        r.w = 1.0f / (1.0f + __expf(-val.w));
        *reinterpret_cast<float4*>(Y + idx + v * 4) = r;
      }
    } else {
      // Tail handling for elements that don't fill a full vector.
      #pragma unroll
      for (int i = 0; i < VecSize; ++i) {
        int64_t j = idx + i;
        if (j < N) {
          float val = X[j];
          Y[j] = 1.0f / (1.0f + __expf(-val));
        }
      }
    }
  }
}
torch::Tensor sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);
  int64_t N = x_c.numel();
  constexpr int VecSize = 8;
  constexpr int Threads = 256;
  int64_t num_vec_groups = (N + VecSize - 1) / VecSize;
  int64_t blocks64 = (num_vec_groups + Threads - 1) / Threads;
  if (blocks64 < 1) blocks64 = 1;
  // Cap grid size to a multiple of the number of SMs to reduce scheduling
  // overhead and improve achieved occupancy, while the grid-stride loop
  // inside the kernel still covers all elements for large N.
  int device_id = 0;
  cudaGetDevice(&device_id);
  int sm_count = 1;
  cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device_id);
  int64_t max_blocks = (int64_t)sm_count * 64; // ~64 blocks per SM for good occupancy without oversubscription
  if (max_blocks < 1) max_blocks = 1;
  if (blocks64 > max_blocks) blocks64 = max_blocks;
  if (blocks64 > 2147483647LL) blocks64 = 2147483647LL; // avoid overflow of grid.x
  dim3 grid((unsigned int)blocks64);
  dim3 block(Threads);
  c10::cuda::CUDAStream stream = at::cuda::getCurrentCUDAStream();
  sigmoid_kernel<VecSize><<<grid, block, 0, stream.stream()>>>(
      x_c.data_ptr<float>(),
      y.data_ptr<float>(),
      N
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "sigmoid_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

sigmoid_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["sigmoid_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Sigmoid activation using a custom CUTE/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.sigmoid_forward(x)

